def countStraightWords(board, word):
    m, n = len(board), len(board[0])
    codes = [ord(ch) - 96 for ch in word]
    L = len(codes)
    total = 0
    for r in range(m):
        for c in range(n):
            if board[r][c] != codes[0]:
                continue
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    er, ec = r + dr * (L - 1), c + dc * (L - 1)
                    if not (0 <= er < m and 0 <= ec < n):
                        continue
                    k = 1
                    while k < L and board[r + dr * k][c + dc * k] == codes[k]:
                        k += 1
                    if k == L:
                        total += 1
    return total
